function validate(input) {
  const [{ Product = [], Invoice = [] }] = input;
  const products = new Set(), names = new Set(), invoices = new Set();
  for (const [id, name] of Product) {
    if (id === null || name === null) return 'Product rows may not contain null.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    if (!/^[a-z]+$/.test(name)) return `Product name ${name} must be lowercase letters.`;
    if (names.has(name)) return `Product name ${name} appears twice.`;
    products.add(id);
    names.add(name);
  }
  for (const row of Invoice) {
    if (row.some((v) => v === null)) return 'Invoice rows may not contain null.';
    if (invoices.has(row[0])) return `invoice_id ${row[0]} appears twice in Invoice.`;
    if (!products.has(row[1])) return `Invoice ${row[0]} names unknown product ${row[1]}.`;
    if (row.slice(2).some((v) => v < 0)) return `Invoice ${row[0]} has a negative amount.`;
    invoices.add(row[0]);
  }
  return null;
}

